const jobs = new Map(); // job_id -> { status: 'running' | 'cancelled' }

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function requireJobId(args) {
  if (!args || !isNonEmptyString(args.job_id)) {
    const error = new Error('job_id is required and must be a non-empty string');
    error.code = -32602;
    throw error;
  }
  return args.job_id;
}

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job identified by job_id. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job identified by job_id. Rejects missing or already-cancelled jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name === 'start_job') {
    const job_id = requireJobId(args);
    const existing = jobs.get(job_id);
    if (existing && existing.status === 'running') {
      const error = new Error(`job ${job_id} is already running`);
      error.code = -32602;
      throw error;
    }
    jobs.set(job_id, { status: 'running' });
    return {
      content: [{ type: 'text', text: `job ${job_id} is running` }]
    };
  }

  if (name === 'cancel_job') {
    const job_id = requireJobId(args);
    const job = jobs.get(job_id);
    if (!job) {
      const error = new Error(`job ${job_id} not found`);
      error.code = -32602;
      throw error;
    }
    if (job.status === 'cancelled') {
      const error = new Error(`job ${job_id} is already cancelled`);
      error.code = -32602;
      throw error;
    }
    job.status = 'cancelled';
    return {
      content: [{ type: 'text', text: `job ${job_id} cancelled` }]
    };
  }

  const error = new Error(`unknown tool: ${name}`);
  error.code = -32602;
  throw error;
}
"}

